import { sql } from "drizzle-orm";
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";

/**
 * Database schema (SQLite via Drizzle ORM).
 *
 * Conventions:
 * - ids are random UUID strings generated by the application;
 * - timestamps are ISO-8601 strings in UTC;
 * - flexible, versioned payloads (evaluation results, metrics) are JSON text
 *   columns, while anything we filter or join on is a real column.
 *
 * After editing, run `npm run db:generate` to create a migration.
 */

const timestamps = {
  createdAt: text("created_at").notNull().default(sql`(strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))`),
};

/**
 * Users. Until authentication exists, every browser gets an anonymous user
 * (cookie-based). Real accounts will attach to these rows rather than
 * replace them, so practice history is preserved.
 */
export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  kind: text("kind", { enum: ["anonymous"] }).notNull().default("anonymous"),
  ...timestamps,
});

/**
 * Snapshot of each task version that has been attempted. Task content is
 * authored in `src/content`; this table records exactly what the student saw.
 */
export const speakingTasks = sqliteTable(
  "speaking_tasks",
  {
    id: text("id").notNull(),
    version: integer("version").notNull(),
    level: text("level").notNull(),
    part: integer("part").notNull(),
    title: text("title").notNull(),
    content: text("content", { mode: "json" }).notNull(),
    ...timestamps,
  },
  (table) => [uniqueIndex("speaking_tasks_id_version_uq").on(table.id, table.version)],
);

export const speakingAttempts = sqliteTable(
  "speaking_attempts",
  {
    id: text("id").primaryKey(),
    userId: text("user_id").notNull().references(() => users.id),
    taskId: text("task_id").notNull(),
    taskVersion: integer("task_version").notNull(),
    /** 1-based, per user and task. */
    attemptNumber: integer("attempt_number").notNull(),
    /** The attempt this one retries (null for a first attempt). */
    previousAttemptId: text("previous_attempt_id"),
    /** Snapshot of the retry focus shown to the student before this attempt. */
    retryFocus: text("retry_focus", { mode: "json" }),
    status: text("status", {
      enum: ["uploaded", "processing", "transcribing", "evaluating", "completed", "failed"],
    }).notNull(),
    failureStage: text("failure_stage", { enum: ["transcription", "evaluation"] }),
    failureCode: text("failure_code"),
    /** Number of times processing has been started (initial run + manual retries). */
    processingRuns: integer("processing_runs").notNull().default(0),
    processingStartedAt: text("processing_started_at"),
    completedAt: text("completed_at"),
    /** Deterministic speech metrics (see domain/speaking/metrics.ts). */
    metrics: text("metrics", { mode: "json" }),
    ...timestamps,
    updatedAt: text("updated_at").notNull(),
  },
  (table) => [
    uniqueIndex("speaking_attempts_user_task_number_uq").on(
      table.userId,
      table.taskId,
      table.attemptNumber,
    ),
    index("speaking_attempts_user_task_idx").on(table.userId, table.taskId),
  ],
);

/** Reference to stored audio. Bytes live in the audio storage provider, not the database. */
export const recordings = sqliteTable(
  "recordings",
  {
    id: text("id").primaryKey(),
    attemptId: text("attempt_id").notNull().references(() => speakingAttempts.id),
    storageProvider: text("storage_provider").notNull(),
    storageKey: text("storage_key").notNull(),
    mimeType: text("mime_type").notNull(),
    sizeBytes: integer("size_bytes").notNull(),
    durationMs: integer("duration_ms").notNull(),
    ...timestamps,
  },
  (table) => [uniqueIndex("recordings_attempt_uq").on(table.attemptId)],
);

export const transcripts = sqliteTable(
  "transcripts",
  {
    id: text("id").primaryKey(),
    attemptId: text("attempt_id").notNull().references(() => speakingAttempts.id),
    provider: text("provider").notNull(),
    model: text("model").notNull(),
    text: text("text").notNull(),
    language: text("language"),
    latencyMs: integer("latency_ms"),
    ...timestamps,
  },
  (table) => [index("transcripts_attempt_idx").on(table.attemptId)],
);

/**
 * AI evaluations. Every row records which methodology produced it
 * (evaluator, rubric and schema versions + provider/model + prompt hash),
 * so scores remain interpretable as the methodology evolves.
 * An attempt may have several evaluations (e.g. re-evaluated with a newer
 * evaluator); the latest is the one shown.
 */
export const evaluations = sqliteTable(
  "evaluations",
  {
    id: text("id").primaryKey(),
    attemptId: text("attempt_id").notNull().references(() => speakingAttempts.id),
    transcriptId: text("transcript_id").notNull().references(() => transcripts.id),
    evaluatorVersion: text("evaluator_version").notNull(),
    rubricVersion: text("rubric_version").notNull(),
    schemaVersion: integer("schema_version").notNull(),
    promptHash: text("prompt_hash").notNull(),
    provider: text("provider").notNull(),
    model: text("model").notNull(),
    overallLevel: text("overall_level").notNull(),
    result: text("result", { mode: "json" }).notNull(),
    latencyMs: integer("latency_ms"),
    inputTokens: integer("input_tokens"),
    outputTokens: integer("output_tokens"),
    ...timestamps,
  },
  (table) => [index("evaluations_attempt_idx").on(table.attemptId)],
);

/** Append-only product analytics events. */
export const analyticsEvents = sqliteTable(
  "analytics_events",
  {
    id: text("id").primaryKey(),
    name: text("name").notNull(),
    source: text("source", { enum: ["client", "server"] }).notNull(),
    userId: text("user_id"),
    taskId: text("task_id"),
    attemptId: text("attempt_id"),
    properties: text("properties", { mode: "json" }),
    /** When the event happened (client clock for client events). */
    occurredAt: text("occurred_at").notNull(),
    /** When the server stored it. */
    ...timestamps,
  },
  (table) => [
    index("analytics_events_name_idx").on(table.name),
    index("analytics_events_user_idx").on(table.userId),
  ],
);
